import sys
import math

MOD = 10**9 + 7

def mod_inverse(x, p):
    return pow(x, p-2, p)

def expected_length(m):
    phi = list(range(m+1))
    for i in range(2, m+1):
        if phi[i] == i:
            for j in range(i, m+1, i):
                phi[j] *= (i - 1)
                phi[j] //= i

    sum_phi = sum(phi[1:m+1])
    P = sum_phi
    Q = m

    Q_inv = mod_inverse(Q, MOD)
    result = (P * Q_inv) % MOD
    return result

def main():
    input_data = sys.stdin.read().strip()
    m = int(input_data)
    print(expected_length(m))

if __name__ == "__main__":
    main()

